    char str[] = "ABCDEFGH";
    char *fir_str;
    char *end_str;
    fir_str = &str[0];
    end_str = &str[strlen(str) - 1];
    while(fir_str < end_str) {
        char temp = *fir_str;
        *fir_str = *end_str;
        *end_str = temp;
        fir_str++;
        end_str--;
    }
    for(int i = 1; i < strlen(str); i += 2) {
        printf("%c", str[i]);
    }
}

class Parent {
    int x, y;
    Parent(int x, int y) {          // ①
        this.x = x;
        this.y = y;
    }
    int getT() {                    // ②
        return x * y;
    }
}
class Child extends Parent {
    int x;
    Child(int x) {                  // ③
        super(x + 1, x);
        this.x = x;
    }
    int getT(int n) {               // ④
        return super.getT() + n;
    }
}
class Main {
    public static void main(String[] args) {    // ⑤
        Parent parent = new Child(3);           // ⑥
        System.out.println(parent.getT());      // ⑦
    }
}

#include <stdio.h>
typedef struct {
    int accNum;
    double bal;
} BankAcc;
double sim_pow(double base, int year) {
    int i;
    double r = 1.0;
    for(i = 0; i < year; i++) {
        r = r * base;
    }
    return r;
}
void initAcc(BankAcc *acc, int x, double y) {
    acc->accNum = x;
    acc->bal = y;
}
void xxx(BankAcc *acc, double *en) {
    if (*en > 0 && *en < acc->bal) {
        acc->bal = acc->bal - *en;
    } else {
        acc->bal = acc->bal + *en;
    }
}
void yyy(BankAcc *acc) {
    acc->bal = acc->bal * sim_pow((1 + 0.1), 3);
}
int main() {
    BankAcc myAcc;
    initAcc(&myAcc, 9981, 2200.0);
    double amount = 100.0;
    xxx(&myAcc, &amount);
    yyy(&myAcc);
    printf("%d and %.2f", myAcc.accNum, myAcc.bal);
    return 0;
}

